--
-- Table structure for table `order_assignments`
--

DROP TABLE IF EXISTS `order_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_assignments` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `role` varchar(32) NOT NULL,
  `state` varchar(32) NOT NULL,
  `assigned_by` int(11) DEFAULT NULL,
  `invited_by` int(11) DEFAULT NULL,
  `assigned_at` datetime NOT NULL DEFAULT current_timestamp(),
  `accepted_at` datetime DEFAULT NULL,
  `removed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_order_employee` (`order_id`,`employee_id`),
  UNIQUE KEY `uq_order_employee_role` (`order_id`,`employee_id`,`role`),
  KEY `fk_oa_emp` (`employee_id`),
  KEY `fk_oa_assigned_by` (`assigned_by`),
  KEY `fk_oa_invited_by` (`invited_by`),
  KEY `idx_order_role_active` (`order_id`,`role`,`removed_at`),
  KEY `idx_order_employee_active` (`order_id`,`employee_id`,`removed_at`),
  CONSTRAINT `fk_oa_assigned_by` FOREIGN KEY (`assigned_by`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_oa_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_oa_invited_by` FOREIGN KEY (`invited_by`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_oa_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `order_assignments`
--

