/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_orders_status_history_after_update
AFTER UPDATE ON orders
FOR EACH ROW
BEGIN
  IF NOT (OLD.status <=> NEW.status) THEN
    INSERT INTO order_status_history (
      order_id,
      old_status,
      new_status,
      changed_at,
      changed_by,
      source
    ) VALUES (
      NEW.id,
      OLD.status,
      NEW.status,
      NOW(),
      @app_user_id,
      'orders_status_trigger'
    );
  END IF;
END */;;
DELIMITER ;
